'use strict';

const fs = require('fs');
const path = require('path');

// Node resolves the package scope of every module it loads from dist/ to the
// nearest package.json. Without one in dist/ that is the runtime root manifest,
// and Node parses its exports map (several hundred entries) again for each
// module. The gateway bundle still loads several hundred dist/ modules for
// plugins, workers and the CLI, so a small manifest in dist/ removes that work.
const OPENCLAW_DIST_PACKAGE_SCOPE_FILE = path.join('dist', 'package.json');
const OPENCLAW_DIST_PACKAGE_SCOPE_MARKER =
  'Generated by LobsterAI. Gives dist/ a small package scope; see scripts/openclaw-dist-package-scope.cjs.';

const OpenClawDistPackageScopeStatus = Object.freeze({
  Created: 'created',
  Updated: 'updated',
  Unchanged: 'unchanged',
  Removed: 'removed',
  Skipped: 'skipped',
});

const OpenClawDistPackageScopeSkipReason = Object.freeze({
  BundleMissing: 'bundle-missing',
  DistMissing: 'dist-missing',
  UnreviewedTarget: 'unreviewed-target',
  UnsupportedRootManifest: 'unsupported-root-manifest',
  ProtectedExisting: 'protected-existing',
});

const ROOT_PACKAGE_NAME = 'openclaw';
const ROOT_PACKAGE_TYPE = 'module';
// Other targets run the whole gateway from dist/ instead of the bundle. That
// layout has not been checked with a package scope in dist/.
const REVIEWED_TARGET_PREFIX = 'win-';

function readJson(filePath) {
  try {
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * `name` is left out on purpose: OpenClaw finds its package root by walking up
 * to the package.json named "openclaw", and that must stay the runtime root.
 * `version` mirrors the root so a reader that takes the nearest manifest still
 * reports the right version.
 */
function buildOpenClawDistPackageScopeContent(rootManifest) {
  return `${JSON.stringify({
    '//': OPENCLAW_DIST_PACKAGE_SCOPE_MARKER,
    type: rootManifest.type,
    version: rootManifest.version,
  }, null, 2)}\n`;
}

function isGeneratedOpenClawDistPackageScope(content) {
  return content.includes(OPENCLAW_DIST_PACKAGE_SCOPE_MARKER);
}

function ensureOpenClawDistPackageScope(runtimeRoot) {
  const scopePath = path.join(runtimeRoot, OPENCLAW_DIST_PACKAGE_SCOPE_FILE);
  const existing = fs.existsSync(scopePath) ? fs.readFileSync(scopePath, 'utf8') : null;
  const skip = (reason) => {
    // A runtime that no longer qualifies must not keep a stale generated scope.
    if (existing !== null && isGeneratedOpenClawDistPackageScope(existing)) {
      fs.rmSync(scopePath);
      return { status: OpenClawDistPackageScopeStatus.Removed, reason };
    }
    return { status: OpenClawDistPackageScopeStatus.Skipped, reason };
  };

  if (existing !== null && !isGeneratedOpenClawDistPackageScope(existing)) {
    return {
      status: OpenClawDistPackageScopeStatus.Skipped,
      reason: OpenClawDistPackageScopeSkipReason.ProtectedExisting,
    };
  }
  if (!fs.existsSync(path.join(runtimeRoot, 'dist'))) {
    return skip(OpenClawDistPackageScopeSkipReason.DistMissing);
  }
  if (!fs.existsSync(path.join(runtimeRoot, 'gateway-bundle.mjs'))) {
    return skip(OpenClawDistPackageScopeSkipReason.BundleMissing);
  }
  const target = readJson(path.join(runtimeRoot, 'runtime-build-info.json'))?.target;
  if (typeof target !== 'string' || !target.startsWith(REVIEWED_TARGET_PREFIX)) {
    return skip(OpenClawDistPackageScopeSkipReason.UnreviewedTarget);
  }
  const rootManifest = readJson(path.join(runtimeRoot, 'package.json'));
  if (rootManifest?.name !== ROOT_PACKAGE_NAME
    || rootManifest.type !== ROOT_PACKAGE_TYPE
    || typeof rootManifest.version !== 'string'
    || !rootManifest.version) {
    return skip(OpenClawDistPackageScopeSkipReason.UnsupportedRootManifest);
  }

  const expected = buildOpenClawDistPackageScopeContent(rootManifest);
  if (existing === expected) {
    return { status: OpenClawDistPackageScopeStatus.Unchanged };
  }
  fs.writeFileSync(scopePath, expected, 'utf8');
  return {
    status: existing === null
      ? OpenClawDistPackageScopeStatus.Created
      : OpenClawDistPackageScopeStatus.Updated,
  };
}

module.exports = {
  OPENCLAW_DIST_PACKAGE_SCOPE_FILE,
  OPENCLAW_DIST_PACKAGE_SCOPE_MARKER,
  OpenClawDistPackageScopeStatus,
  OpenClawDistPackageScopeSkipReason,
  buildOpenClawDistPackageScopeContent,
  ensureOpenClawDistPackageScope,
};
